add("vsa3", ("दल-बदल क्या है? इसे कैसे रोका गया?", "પક્ષાંતર શું છે? તેને કેવી રીતે રોકાયું?"),
    {0: ("जिस दल से चुने गए उसे छोड़कर दूसरे दल में चले जाना दल-बदल है।", "જે પક્ષમાંથી ચૂંટાયા હોય તે છોડી બીજા પક્ષમાં જોડાવું એ પક્ષાંતર છે."), 1: ("एक संविधान संशोधन (1985) से दल बदलने पर सांसद या विधायक की सीट चली जाती है।", "એક બંધારણીય સુધારા (1985)થી પક્ષ બદલવા પર સાંસદ કે ધારાસભ્યની બેઠક જાય છે.")})
add("sa1", ("उदाहरण सहित एकदलीय, द्विदलीय और बहुदलीय व्यवस्था की तुलना कीजिए।", "ઉદાહરણો સાથે એકપક્ષ, દ્વિપક્ષ અને બહુપક્ષ પ્રથાની સરખામણી કરો."),
    {0: ("एकदलीय व्यवस्था: केवल एक दल को सरकार चलाने की अनुमति, जैसे चीन में; यह लोकतांत्रिक नहीं क्योंकि मतदाताओं के पास असली विकल्प नहीं।", "એકપક્ષ પ્રથા: ફક્ત એક પક્ષને સરકાર ચલાવવાની છૂટ, જેમ કે ચીનમાં; તે લોકશાહી નથી કારણ કે મતદારો પાસે ખરો વિકલ્પ નથી."),
     1: ("द्विदलीय व्यवस्था: सत्ता आमतौर पर दो मुख्य दलों के बीच बदलती है, हालाँकि दूसरे दल भी होते हैं, जैसे अमेरिका और ब्रिटेन में।", "દ્વિપક્ષ પ્રથા: સત્તા સામાન્ય રીતે બે મુખ્ય પક્ષો વચ્ચે બદલાય છે, જોકે બીજા પક્ષો પણ હોય છે, જેમ કે અમેરિકા અને યુનાઇટેડ કિંગડમમાં."),
     2: ("बहुदलीय व्यवस्था: कई दल होड़ करते हैं और दो से अधिक दलों को अकेले या गठबंधन में सत्ता में आने का ठीक-ठाक अवसर होता है, जैसे भारत में।", "બહુપક્ષ પ્રથા: અનેક પક્ષો સ્પર્ધા કરે છે અને બેથી વધુ પક્ષોને એકલા કે ગઠબંધનમાં સત્તામાં આવવાની વાજબી તક હોય છે, જેમ કે ભારતમાં.")})
add("sa2", ("भारत के किन्हीं तीन राष्ट्रीय दलों का वर्णन कीजिए।", "ભારતના કોઈ પણ ત્રણ રાષ્ટ્રીય પક્ષોનું વર્ણન કરો."),
    {0: ("भारतीय राष्ट्रीय कांग्रेस: 1885 में स्थापित; मध्यमार्गी; धर्मनिरपेक्षता और कमज़ोर वर्गों तथा अल्पसंख्यकों के कल्याण का समर्थन; 2004 से 2014 तक यूपीए का नेतृत्व।", "ભારતીય રાષ્ટ્રીય કૉંગ્રેસ: 1885માં સ્થપાઈ; મધ્યમમાર્ગી; બિનસાંપ્રદાયિકતા અને નબળા વર્ગો તથા લઘુમતીઓના કલ્યાણનું સમર્થન; 2004થી 2014 સુધી UPAનું નેતૃત્વ."),
     1: ("भारतीय जनता पार्टी: 1980 में भारतीय जनसंघ (1951) से बनी; सांस्कृतिक राष्ट्रवाद और एकात्म मानववाद; एनडीए का नेतृत्व और 2014, 2019 तथा 2024 के बाद सरकार बनाई।", "ભારતીય જનતા પાર્ટી: 1980માં ભારતીય જનસંઘ (1951)માંથી બની; સાંસ્કૃતિક રાષ્ટ્રવાદ અને એકાત્મ માનવવાદ; NDAનું નેતૃત્વ અને 2014, 2019 તથા 2024 પછી સરકાર રચી."),
     2: ("बहुजन समाज पार्टी: 1984 में कांशीराम द्वारा स्थापित; दलितों, आदिवासियों, पिछड़ी जातियों और धार्मिक अल्पसंख्यकों का प्रतिनिधित्व; साहू महाराज, फुले, पेरियार और आंबेडकर से प्रेरित; मुख्य आधार उत्तर प्रदेश।", "બહુજન સમાજ પાર્ટી: 1984માં કાંશીરામે સ્થાપી; દલિતો, આદિવાસીઓ, પછાત વર્ગો અને ધાર્મિક લઘુમતીઓનું પ્રતિનિધિત્વ; શાહૂ મહારાજ, ફુલે, પેરિયાર અને આંબેડકરથી પ્રેરિત; મુખ્ય આધાર ઉત્તર પ્રદેશ.")})
add("sa3", ("भारत में राजनीतिक दलों में सुधार के लिए क्या क़दम उठाए गए हैं?", "ભારતમાં રાજકીય પક્ષોમાં સુધારા માટે કયાં પગલાં લેવાયાં છે?"),
    {0: ("दल-बदल विरोधी क़ानून: संविधान संशोधन (1985) से दल बदलने पर सांसद या विधायक की सीट जाती है; इससे दल-बदल घटा पर असहमति कठिन हुई।", "પક્ષાંતર વિરોધી કાયદો: બંધારણીય સુધારા (1985)થી પક્ષ બદલવા પર સાંસદ કે ધારાસભ્યની બેઠક જાય છે; તેનાથી પક્ષાંતર ઘટ્યું પણ મતભેદ મુશ્કેલ બન્યો."),
     1: ("सर्वोच्च न्यायालय का आदेश (2003): हर उम्मीदवार को संपत्ति और लंबित आपराधिक मामलों का शपथपत्र देना होता है, जो सार्वजनिक किया जाता है।", "સર્વોચ્ચ અદાલતનો આદેશ (2003): દરેક ઉમેદવારે મિલકત અને બાકી ફોજદારી કેસોનું સોગંદનામું આપવું પડે છે, જે જાહેર કરાય છે."),
     2: ("चुनाव आयोग का आदेश: दलों को सांगठनिक चुनाव कराने और आयकर रिटर्न भरने होते हैं, हालाँकि कभी-कभी यह औपचारिकता होती है।", "ચૂંટણી પંચનો આદેશ: પક્ષોએ સંગઠનાત્મક ચૂંટણીઓ કરાવવી અને આવકવેરા રિટર્ન ભરવાં પડે છે, જોકે ક્યારેક આ ઔપચારિકતા હોય છે.")})
add("la1", ("'भारत में बहुदलीय व्यवस्था है।' इसके कारण और राज्यस्तरीय दलों की भूमिका समझाइए।", "'ભારતમાં બહુપક્ષ પ્રથા છે.' તેનાં કારણો અને રાજ્ય કક્ષાના પક્ષોની ભૂમિકા સમજાવો."),
    {0: ("बहुदलीय व्यवस्था में कई दल होड़ करते हैं और दो से अधिक दलों को अकेले या गठबंधन में सत्ता में आने का ठीक-ठाक अवसर होता है।", "બહુપક્ષ પ્રથામાં અનેક પક્ષો સ્પર્ધા કરે છે અને બેથી વધુ પક્ષોને એકલા કે ગઠબંધનમાં સત્તામાં આવવાની વાજબી તક હોય છે."),
     1: ("दलीय व्यवस्था लंबे समय में विकसित होती है, जो समाज की प्रकृति, उसके सामाजिक और क्षेत्रीय विभाजनों, राजनीति के इतिहास और चुनाव प्रणाली पर निर्भर है।", "પક્ષ પ્રથા લાંબા ગાળે વિકસે છે, જે સમાજના સ્વરૂપ, તેનાં સામાજિક અને પ્રાદેશિક વિભાજનો, રાજકારણના ઇતિહાસ અને ચૂંટણી પ્રથા પર આધાર રાખે છે."),
     2: ("भारत की सामाजिक और भौगोलिक विविधता को दो या तीन दल भी आसानी से नहीं समेट सकते, इसलिए कई दल अलग-अलग हितों और क्षेत्रों का प्रतिनिधित्व करते हैं।", "ભારતની સામાજિક અને ભૌગોલિક વિવિધતા બે કે ત્રણ પક્ષો પણ સહેલાઈથી સમાવી શકતા નથી, તેથી અનેક પક્ષો જુદાં જુદાં હિતો અને પ્રદેશોનું પ્રતિનિધિત્વ કરે છે."),
     3: ("पिछले तीन दशकों में राज्यस्तरीय दलों की संख्या और ताक़त बढ़ी, जिससे संसद अधिक विविध हुई; 1989 से 2014 तक कोई राष्ट्रीय दल अकेले बहुमत नहीं पा सका।", "છેલ્લા ત્રણ દાયકામાં રાજ્ય કક્ષાના પક્ષોની સંખ્યા અને શક્તિ વધી, જેથી સંસદ વધુ વૈવિધ્યસભર બની; 1989થી 2014 સુધી કોઈ રાષ્ટ્રીય પક્ષ એકલો બહુમતી મેળવી શક્યો નહિ."),
     4: ("1996 से लगभग हर राज्यस्तरीय दल किसी राष्ट्रीय गठबंधन सरकार का हिस्सा रहा है, जिससे संघवाद और लोकतंत्र मज़बूत हुए।", "1996થી લગભગ દરેક રાજ્ય કક્ષાનો પક્ષ કોઈ રાષ્ટ્રીય ગઠબંધન સરકારનો ભાગ રહ્યો છે, જેથી સમવાયતંત્ર અને લોકશાહી મજબૂત બન્યાં.")})
add("la2", ("राजनीतिक दलों को अधिक लोकतांत्रिक बनाने के सुधार सुझाइए, और नागरिकों की भूमिका समझाइए।", "રાજકીય પક્ષોને વધુ લોકશાહી બનાવવાના સુધારા સૂચવો, અને નાગરિકોની ભૂમિકા સમજાવો."),
    {0: ("दलों के आंतरिक कामकाज के नियमन का क़ानून: सदस्यों की सूची, दल के संविधान का पालन, विवाद सुलझाने के लिए स्वतंत्र प्राधिकारी, और सबसे बड़े पदों के लिए खुले चुनाव।", "પક્ષોની આંતરિક બાબતોના નિયમનનો કાયદો: સભ્યોનું રજિસ્ટર, પક્ષના બંધારણનું પાલન, વિવાદ ઉકેલવા સ્વતંત્ર સત્તામંડળ, અને સર્વોચ્ચ હોદ્દાઓ માટે ખુલ્લી ચૂંટણીઓ."),
     1: ("दलों के लिए लगभग एक-तिहाई टिकट महिलाओं को देना और दल के फ़ैसले लेने वाले निकायों में महिलाओं का कोटा अनिवार्य करना।", "પક્ષો માટે આશરે એક-તૃતીયાંશ ટિકિટ સ્ત્રીઓને આપવી અને પક્ષનાં નિર્ણય લેતાં અંગોમાં સ્ત્રીઓનો ક્વોટા ફરજિયાત કરવો."),
     2: ("चुनाव का सरकारी ख़र्च: सरकार पिछले चुनाव में मिले वोटों के आधार पर दलों को पैसा या चीज़ें (पेट्रोल, काग़ज़, फ़ोन) दे।", "ચૂંટણીઓનું સરકારી ભંડોળ: સરકાર ગઈ ચૂંટણીમાં મળેલા મતોના આધારે પક્ષોને પૈસા કે વસ્તુઓ (પેટ્રોલ, કાગળ, ટેલિફોન) આપે."),
     3: ("क़ानूनी सुधारों में सावधानी चाहिए, क्योंकि ज़रूरत से ज़्यादा नियंत्रण उलटा असर कर सकता है और दल क़ानून से बचने के रास्ते ढूँढ़ सकते हैं।", "કાનૂની સુધારામાં કાળજી જોઈએ, કારણ કે વધુ પડતું નિયમન ઊલટી અસર કરી શકે અને પક્ષો કાયદામાંથી છટકવાના રસ્તા શોધી શકે."),
     4: ("नागरिक याचिकाओं, प्रचार, आंदोलनों, मीडिया और जन आंदोलनों से दलों पर दबाव डाल सकते हैं, और सुधार चाहने वाले ख़ुद दलों में शामिल हो सकते हैं।", "નાગરિકો અરજીઓ, પ્રચાર, આંદોલનો, માધ્યમો અને લોક આંદોલનો દ્વારા પક્ષો પર દબાણ લાવી શકે, અને સુધારા ઇચ્છનારાઓ પોતે પક્ષોમાં જોડાઈ શકે.")})
